/**
 * An Input preset for passwords, with a reveal toggle (`design/components/password-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/password-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/password-input.module.css'
import Input from './Input'

export interface PasswordInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Has a default, unlike Input's plain passthrough, because a password field without one breaks
   * password managers and WCAG 1.3.5. Sign-up flows pass `'new-password'`. Other values belong
   * to other members (one-time codes use OTPInput).
   */
  autoComplete?: 'current-password' | 'new-password'
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  name?: string
  onChange?: (value: string, event: Event) => void
  placeholder?: string
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * The toggle's accessible name ("Show password"). The member has no built-in text.
   */
  toggleLabel: string
  value?: string
}

/** An Input preset for passwords, with a reveal toggle. */
export default function PasswordInput(given: PasswordInputProps): JSX.Element {
  const props = mergeProps(
    {
      size: 'md',
      disabled: false,
      readOnly: false,
      invalid: false,
      autoComplete: 'current-password',
    } as Defaults<
      PasswordInputProps,
      'size' | 'disabled' | 'readOnly' | 'invalid' | 'autoComplete'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const revealed = createCell(false)
    const held = createCell({
      start: null as number | null,
      end: null as number | null,
      direction: 'none' as 'forward' | 'backward' | 'none',
    })
    const frame = elementRef<HTMLElement>()
    const field = createDerived(() => frame.value?.querySelector('input') ?? null)
    const effect1 = () => {
      void (field.value?.setAttribute('spellcheck', 'false'),
      field.value?.setAttribute('autocapitalize', 'off'),
      field.value?.setAttribute('autocorrect', 'off'))
    }
    onMount(effect1)
    const effect2 = () => {
      void (
        held.value.start !== null &&
        held.value.end !== null &&
        (field.value?.setSelectionRange(held.value.start, held.value.end, held.value.direction),
        requestAnimationFrame(() =>
          field.value?.setSelectionRange(held.value.start, held.value.end, held.value.direction),
        ))
      )
    }
    watchEffect(
      createMemo(() => revealed.value),
      effect2,
      false,
    )
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = agentMember({
        member: 'PasswordInput',
        element: () => frame.value?.querySelector('input'),
        state: () => ({
          value: frame.value?.querySelector('input')?.value ?? '',
          revealed: revealed.value,
          disabled: props.disabled,
          invalid: props.invalid,
          readonly: props.readOnly,
        }),
        actions: {},
        secret: ['value'],
      })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <span
        class={styles.password}
        data-size={props.size}
        data-disabled={props.disabled ? '' : undefined}
        data-invalid={props.invalid ? '' : undefined}
        data-readonly={props.readOnly ? '' : undefined}
        data-state={revealed.value ? 'visible' : 'hidden'}
        data-member="password-input"
        ref={frame.attach}
      >
        <Input
          type={revealed.value ? 'text' : 'password'}
          value={props.value}
          defaultValue={props.defaultValue}
          placeholder={props.placeholder}
          size={props.size}
          disabled={props.disabled}
          readOnly={props.readOnly}
          invalid={props.invalid}
          autoComplete={props.autoComplete}
          name={props.name}
          id={props.id}
          aria-label={props['aria-label']}
          aria-labelledby={props['aria-labelledby']}
          aria-describedby={props['aria-describedby']}
          aria-required={props['aria-required']}
          onChange={(next, event) => props.onChange?.(next, event)}
          trailing={
            <button
              class={styles.toggle}
              type="button"
              disabled={props.disabled}
              aria-pressed={revealed.value}
              aria-label={props.toggleLabel}
              onclick={() => (
                (held.value = {
                  start: field.value?.selectionStart ?? null,
                  end: field.value?.selectionEnd ?? null,
                  direction: field.value?.selectionDirection ?? 'none',
                }),
                (revealed.value = !revealed.value)
              )}
            >
              {revealed.value ? (
                <Icon name="hidden" size={props.size} />
              ) : (
                <Icon name="visible" size={props.size} />
              )}
            </button>
          }
        />
      </span>
    )
  })
}
